SELECT symbol, interval_code, open_time, close_time, open_price, high_price, low_price, close_price, number_of_trades, closed, ingestion_source, created_at, updated_at FROM crypto_ai.candle WHERE (symbol='EGLDUSDT' AND interval_code='1m' AND open_time IN ('2026-10-11 20:54:00','2026-10-11 20:59:00','2026-10-11 21:00:00','2026-10-11 22:39:00','2026-10-11 22:42:00','2026-10-11 22:43:00')) OR (symbol='XRPUSDT' AND interval_code='1m' AND open_time IN ('2026-10-12 02:34:00','2026-10-12 03:29:00')) OR (symbol='DOGEUSDT' AND interval_code='1m' AND open_time IN ('2026-10-12 04:01:00','2026-10-12 04:25:00')) OR (symbol='SHIBUSDT' AND interval_code='1m' AND open_time IN ('2026-10-12 06:35:00','2026-10-12 07:14:00')) OR (symbol='ACEUSDT' AND interval_code='1m' AND open_time IN ('2026-10-12 09:56:00','2026-10-12 10:04:00')) OR (symbol='EGLDUSDT' AND interval_code='5m' AND open_time IN ('2026-10-11 22:30:00','2026-10-11 22:35:00')) ORDER BY symbol, interval_code, open_time LIMIT 50;